class Solution:
    def maxConsecutive(self, bottom: int, top: int, special: List[int]) -> int:
        special.sort()
        ans, prev = 0, bottom - 1
        for s in special:
            ans = max(ans, s - prev - 1)
            prev = s
        return max(ans, top - prev)

c.cpp:
class Solution {
public:
    int maxConsecutive(int bottom, int top, vector<int>& special) {
        sort(special.begin(), special.end());
        int ans = 0, prev = bottom - 1;
        for (int s : special) { ans = max(ans, s - prev - 1); prev = s; }
        return max(ans, top - prev);
    }
};

c.java:
class Solution {
    public int maxConsecutive(int bottom, int top, int[] special) {
        Arrays.sort(special);
        int ans = 0, prev = bottom - 1;
        for (int s : special) { ans = Math.max(ans, s - prev - 1); prev = s; }
        return Math.max(ans, top - prev);
    }
}

